var n=`0532-jareesh`;var t=`world-0532`;var o=`SA`;var r=`western-asia`;var a=4;var s=79;var u={en:`Jareesh`,ua:`Джаріш`};var d={en:`A traditional dish from Saudi Arabia, centered on yellow onion, bulgur, chicken thigh, plain yogurt. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Саудівська Аравія. Основні складники: жовта цибуля, булгур, куряче стегно, натуральний йогурт. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,190,`g`],[`unsalted-butter`,55,`g`]]},{en:`Cook the listed ingredients in simmering water for about 40 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 40 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:40,i:[[`bulgur`,450,`g`],[`chicken-stock`,1150,`ml`],[`chicken-thigh`,450,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`plain-yogurt`,180,`g`],[`ground-cumin`,4,`g`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 20 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 20 хвилин до м’якості та готовності.`,t:[`simmering`],m:20,i:[]}];var l={slug:n,id:t,country:`SA`,region:r,servings:4,minutes:79,title:u,text:d,steps:g};export{o as country,l as default,t as id,s as minutes,r as region,a as servings,n as slug,g as steps,d as text,u as title};